<?php
declare(strict_types=1);
namespace Namira;
use PDO;
final class StoreProduction {
 public static function schedule(PDO $db,array $actor,int $item,array $in):void{
  StoreAccess::require($db,$actor,'orders');$i=StoreAccess::item($db,$item,$actor);$due=Security::text($in,'due_at',30,false);if($due!==''&&strtotime($due)===false)throw new HttpError(422,'مهلت معتبر وارد کنید.');$due=$due!==''?date('Y-m-d H:i:s',strtotime($due)):null;$required=!empty($in['quality_required']);
  Db::transaction($db,function()use($db,$actor,$item,$in,$due,$required){Db::query($db,'SELECT item_id FROM store_item_details WHERE item_id=?'.StoreAccess::lock($db),[$item])->fetch();$old=Db::query($db,'SELECT * FROM store_item_schedule WHERE item_id=?',[$item])->fetch();if($old&&(int)($in['schedule_revision']??-1)!==(int)$old['revision'])throw new HttpError(409,'برنامه در پنجره دیگری تغییر کرده است.');if($old)Db::query($db,'UPDATE store_item_schedule SET due_at=?,quality_required=?,revision=revision+1 WHERE item_id=?',[$due,$required?1:0,$item]);else Db::insert($db,'store_item_schedule',['item_id'=>$item,'due_at'=>$due,'quality_required'=>$required?1:0]);StoreAccess::audit($db,$actor,'schedule.save','item',$item,$old?:[],['due_at'=>$due,'quality_required'=>$required]);});
 }
 public static function record(PDO $db,array $actor,int $item,array $in):int{
  StoreAccess::require($db,$actor,'production');return Db::transaction($db,function()use($db,$actor,$item,$in){Db::query($db,'SELECT item_id FROM store_item_details WHERE item_id=?'.StoreAccess::lock($db),[$item])->fetch();$i=StoreAccess::item($db,$item,$actor);if($i['delivery']==='digital'||!in_array($i['status'],['ready','packing','shipped'],true))throw new HttpError(422,'قلم فیزیکی آمادهٔ تولید/ارسال لازم است.');if(!Db::query($db,"SELECT id FROM payments WHERE order_id=? AND status='verified'",[$i['order_id']])->fetchColumn())throw new HttpError(422,'پرداخت تأیید نشده است.');$event=Security::text($in,'event',30);if(!in_array($event,['start','finish','quality'],true))throw new HttpError(422,'عملیات تولید معتبر نیست.');$quantity=StoreCatalog::integer($in['quantity']??1,1,(int)$i['quantity']);$quality=$event==='quality'?Security::text($in,'quality',20):'';if($event==='quality'&&!in_array($quality,['pass','fail'],true))throw new HttpError(422,'نتیجه کنترل کیفیت معتبر نیست.');$note=Security::text($in,'note',2000,false);
   if($event==='finish'&&(int)Db::query($db,"SELECT COALESCE(SUM(quantity),0) FROM store_production_records WHERE item_id=? AND event='finish'",[$item])->fetchColumn()+$quantity>(int)$i['quantity'])throw new HttpError(422,'تعداد تولیدشده بیش از سفارش است.');$id=Db::insert($db,'store_production_records',['item_id'=>$item,'user_id'=>$actor['id'],'event'=>$event,'quantity'=>$quantity,'quality'=>$quality,'note'=>$note,'created_at'=>date('Y-m-d H:i:s')]);if(!Db::query($db,'SELECT item_id FROM store_item_schedule WHERE item_id=?',[$item])->fetchColumn())Db::insert($db,'store_item_schedule',['item_id'=>$item]);if($event==='start')Db::query($db,'UPDATE store_item_schedule SET started_at=COALESCE(started_at,?),revision=revision+1 WHERE item_id=?',[date('Y-m-d H:i:s'),$item]);if($event==='finish')Db::query($db,'UPDATE store_item_schedule SET completed_at=?,revision=revision+1 WHERE item_id=?',[date('Y-m-d H:i:s'),$item]);StoreAccess::audit($db,$actor,'production.'.$event,'item',$item,[],['record'=>$id,'quantity'=>$quantity,'quality'=>$quality],$note);return $id;
  });
 }
 public static function assertQuality(PDO $db,int $item):void{
  if(!StoreOperationsSchema::ready($db))return;$required=Db::query($db,'SELECT quality_required FROM store_item_schedule WHERE item_id=?',[$item])->fetchColumn();if(!$required)return;$last=Db::query($db,"SELECT quality FROM store_production_records WHERE item_id=? AND event='quality' ORDER BY id DESC LIMIT 1",[$item])->fetchColumn();if($last!=='pass')throw new HttpError(422,'کنترل کیفیت این قلم باید تأیید شود.');
 }
 public static function materials(PDO $db,array $actor,int $product,array $rows):void{
  if(!Permissions::allows($db,$actor,'shop.manage'))throw new HttpError(403,'تنظیم مواد اولیه مجاز نیست.');(new StoreCatalog($db))->get($product,true);if(count($rows)>30)throw new HttpError(422,'تعداد مواد اولیه بیش از حد است.');$clean=[];foreach($rows as $row){if(!empty($row['remove'])||($row['variant_id']??'')==='')continue;$variant=StoreCatalog::integer($row['variant_id'],1);$units=StoreCatalog::integer($row['units']??1,1,1000000);$v=Db::query($db,'SELECT product_id FROM variants WHERE id=?',[$variant])->fetchColumn();if(!$v||(int)$v===$product||isset($clean[$variant]))throw new HttpError(422,'گونهٔ ماده اولیه معتبر، یکتا و مستقل از خود محصول باشد.');$clean[$variant]=$units;}
  Db::transaction($db,function()use($db,$actor,$product,$clean){$before=Db::query($db,'SELECT * FROM store_material_links WHERE product_id=?',[$product])->fetchAll();Db::query($db,'DELETE FROM store_material_links WHERE product_id=?',[$product]);foreach($clean as $variant=>$units)Db::insert($db,'store_material_links',['product_id'=>$product,'variant_id'=>$variant,'units'=>$units]);StoreAccess::audit($db,$actor,'materials.save','product',$product,$before,$clean);});
 }
}
